'use client';
import { motion, useReducedMotion } from 'framer-motion';
import { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState } from 'react';
import { CountUp } from './CountUp';
import { C, TF, compact, fmt, type LedgerStore, type Tf } from './store';
import { cardMotion, spring } from './motionPresets';

export type ChartHandle = { hover: (i: number | null) => void; count: () => number };
const TFS: Tf[] = ['1m', '15m', '1H', '4H', '1D'];
const ma = (c: { c: number }[], k: number) => c.map((_, i) => (i < k - 1 ? null : c.slice(i - k + 1, i + 1).reduce((s, x) => s + x.c, 0) / k));

/** Candlesticks + volume + MA lines, crosshair with OHLC readout, live last-price tag. */
export const ChartCard = forwardRef<ChartHandle, { store: LedgerStore; index: number }>(function ChartCard({ store, index }, ref) {
  const box = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ w: 700, h: 430 });
  const [hover, setHover] = useState<{ i: number; y: number | null } | null>(null);
  const [flash, setFlash] = useState<'fu' | 'fd' | ''>('');
  const [gen, setGen] = useState(0); // bumps when the series is regenerated, so candles stagger in again
  const reduce = useReducedMotion();
  const cur = store.cur, candles = store.candles, n = candles.length;
  const lastPx = useRef(cur.px), lastKey = useRef(cur.s + store.tf);

  useLayoutEffect(() => {
    const el = box.current; if (!el) return;
    const ro = new ResizeObserver(() => setSize({ w: el.clientWidth || 700, h: el.clientHeight || 430 }));
    ro.observe(el); return () => ro.disconnect();
  }, []);
  useEffect(() => {
    const key = cur.s + store.tf;
    if (key !== lastKey.current) { lastKey.current = key; setGen((g) => g + 1); lastPx.current = cur.px; return; }
    if (cur.px !== lastPx.current) { setFlash(cur.px > lastPx.current ? 'fu' : 'fd'); lastPx.current = cur.px; const t = setTimeout(() => setFlash(''), 700); return () => clearTimeout(t); }
  }, [cur.px, cur.s, store.tf]);

  const { w: W, h: H } = size, pr = 62, pt = 26, volH = H * .18, pb = 22;
  const lo = Math.min(...candles.map((c) => c.l)), hi = Math.max(...candles.map((c) => c.h)), pad = (hi - lo) * .08;
  const mn = lo - pad, mx = hi + pad, vmax = Math.max(...candles.map((c) => c.v));
  const cw = (W - pr) / n, bw = Math.max(2, cw * .62), plotH = H - pt - pb - volH - 8;
  const X = (i: number) => i * cw + cw / 2, Y = (v: number) => pt + (1 - (v - mn) / (mx - mn)) * plotH, VY = (v: number) => H - pb - (v / vmax) * volH;
  const path = (arr: (number | null)[]) => arr.map((v, i) => (v == null ? '' : `${arr[i - 1] == null ? 'M' : 'L'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`)).join('');
  const last = candles[n - 1], ly = Y(last.c), lup = last.c >= last.o;
  const hi_ = hover ? Math.min(hover.i, n - 1) : n - 1, hc = candles[hi_], hup = hc.c >= hc.o, hcls = hup ? 'up' : 'down';
  const hy = hover ? (hover.y ?? Y(hc.c)) : 0, hv = mx - ((hy - pt) / plotH) * (mx - mn);
  useImperativeHandle(ref, () => ({ hover: (i) => setHover(i == null ? null : { i, y: null }), count: () => n }), [n]);
  const onMove = (e: React.PointerEvent) => {
    const r = e.currentTarget.getBoundingClientRect(), x = (e.clientX - r.left) * (W / r.width), y = (e.clientY - r.top) * (H / r.height);
    if (x > W - pr) return setHover(null);
    setHover({ i: Math.max(0, Math.min(n - 1, Math.floor(x / cw))), y });
  };
  const chg = ((cur.px - cur.open) / cur.open) * 100;
  const labels = [0, Math.floor(n / 3), Math.floor((2 * n) / 3), n - 1];

  return (
    <motion.section className="card chart-card" aria-label="Price chart" {...cardMotion(index)}>
      <div className="mkt">
        <div className="pair"><span className="coin" style={{ background: cur.col }}>{cur.g || cur.s[0]}</span><div><b>{cur.s} / USD</b><small>{cur.name}</small></div></div>
        <div><CountUp key={cur.s} value={cur.px} decimals={cur.dp} duration={0.35} firstDuration={1.3} className={`price ${flash}`} as="span" /></div>
        <div className="stat"><small>24h change</small><b className={chg >= 0 ? 'up' : 'down'}>{chg >= 0 ? '+' : ''}{chg.toFixed(2)}%</b></div>
        <div className="stat hide-s"><small>24h high</small><b>{fmt(hi, cur.dp)}</b></div>
        <div className="stat hide-s"><small>24h low</small><b>{fmt(lo, cur.dp)}</b></div>
        <div className="stat"><small>24h volume</small><b>${compact(cur.vol)}</b></div>
        <div className="seg" role="radiogroup" aria-label="Candle interval" onKeyDown={(e) => {
          if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
          const i = TFS.indexOf(store.tf), nx = TFS[(i + (e.key === 'ArrowRight' ? 1 : TFS.length - 1)) % TFS.length];
          store.setTf(nx); (e.currentTarget.querySelector(`[data-tf="${nx}"]`) as HTMLElement | null)?.focus(); e.preventDefault();
        }}>
          {TFS.map((t) => (
            <button key={t} role="radio" data-tf={t} aria-checked={store.tf === t} tabIndex={store.tf === t ? 0 : -1} onClick={() => store.setTf(t)}>
              {store.tf === t && <motion.span layoutId="ledger-tf" className="seg-pill" transition={spring} />}{t}
            </button>
          ))}
        </div>
      </div>
      <div className="chart" ref={box} onPointerMove={onMove} onPointerLeave={() => setHover(null)}>
        <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Candlestick chart with volume">
          {[0, 1, 2, 3, 4, 5].map((k) => { const v = mn + ((mx - mn) * k) / 5, y = Y(v); return (
            <g key={k}><line className="gl" x1="0" x2={W - pr} y1={y} y2={y} /><text className="ax" x={W - pr + 8} y={y + 3}>{fmt(v, cur.dp)}</text></g>); })}
          {labels.map((i) => { const d = new Date(candles[i].t * 1000); return (
            <text key={i} className="ax" x={X(i)} y={H - 6} textAnchor="middle">{store.tf === '1D' ? d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}</text>); })}
          <g key={gen}>
            {candles.map((c, i) => {
              const up = c.c >= c.o, col = up ? C.up : C.down, x = X(i), y1 = Y(Math.max(c.o, c.c)), y2 = Y(Math.min(c.o, c.c));
              return (
                <motion.g key={c.t} initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: Math.min(i, n) * 0.014, ease: [0.16, 1, 0.3, 1] }}>
                  <rect x={x - bw / 2} y={VY(c.v)} width={bw} height={H - pb - VY(c.v)} fill={col} opacity=".16" rx="1" />
                  <line x1={x} x2={x} y1={Y(c.h)} y2={Y(c.l)} stroke={col} strokeWidth="1.2" />
                  <rect x={x - bw / 2} y={y1} width={bw} height={Math.max(1.2, y2 - y1)} fill={col} fillOpacity=".9" rx="1.5" />
                </motion.g>
              );
            })}
          </g>
          <path d={path(ma(candles, 20))} fill="none" stroke={C.violet} strokeWidth="1.6" />
          <path d={path(ma(candles, 50))} fill="none" stroke={C.cyan} strokeWidth="1.2" opacity=".75" />
          <line x1="0" x2={W - pr} y1={ly} y2={ly} stroke={lup ? C.up : C.down} strokeDasharray="3 3" opacity=".7" />
          <g transform={`translate(${W - pr + 2} ${ly - 10})`}><rect width={pr - 4} height="20" rx="5" fill={lup ? C.up : C.down} />
            <text x={(pr - 4) / 2} y="14" textAnchor="middle" fontFamily="JetBrains Mono,monospace" fontSize="10.5" fontWeight="600" fill="#0A0A0D">{fmt(last.c, cur.dp)}</text></g>
          {!reduce && <motion.circle cx={X(n - 1)} cy={ly} r={3.5} initial={{ r: 3.5, opacity: 1 }} fill={lup ? C.up : C.down} animate={{ r: [3.5, 7, 3.5], opacity: [1, 0.4, 1] }} transition={{ duration: 1.6, repeat: Infinity }} />}
          {reduce && <circle cx={X(n - 1)} cy={ly} r="3.5" fill={lup ? C.up : C.down} />}
          {hover && <g pointerEvents="none">
            <line x1={X(hi_)} x2={X(hi_)} y1={pt} y2={H - pb} stroke={C.muted} strokeDasharray="3 3" />
            <line x1="0" x2={W - pr} y1={hy} y2={hy} stroke={C.muted} strokeDasharray="3 3" />
            <g transform={`translate(${W - pr + 2} ${hy - 10})`}><rect width={pr - 4} height="20" rx="5" fill={C.text} />
              <text x={(pr - 4) / 2} y="14" textAnchor="middle" fontFamily="JetBrains Mono,monospace" fontSize="10.5" fontWeight="600" fill="#0A0A0D">{fmt(hv, cur.dp)}</text></g>
          </g>}
        </svg>
        <div className="ohlc">
          <span>O <b className={hcls}>{fmt(hc.o, cur.dp)}</b></span><span>H <b className={hcls}>{fmt(hc.h, cur.dp)}</b></span>
          <span>L <b className={hcls}>{fmt(hc.l, cur.dp)}</b></span><span>C <b className={hcls}>{fmt(hc.c, cur.dp)}</b></span>
          <span className={hcls}>{hup ? '+' : ''}{(((hc.c - hc.o) / hc.o) * 100).toFixed(2)}%</span>
        </div>
      </div>
      <div className="legend" aria-hidden="true"><span><i style={{ background: C.violet }} />MA 20</span><span><i style={{ background: C.cyan }} />MA 50</span><span><i style={{ background: C.line, height: 8 }} />volume · {TF[store.tf].n} candles</span></div>
    </motion.section>
  );
});

'use client';
import { animate, useReducedMotion } from 'framer-motion';
import { createElement, useEffect, useRef } from 'react';
import { fmt } from './store';

/** Eases from the last shown value to the new one. Instant under Reduce Motion. */
export function CountUp({ value, decimals = 2, duration = 0.6, firstDuration, prefix = '', suffix = '', className, as = 'b' }:
  { value: number; decimals?: number; duration?: number; firstDuration?: number; prefix?: string; suffix?: string; className?: string; as?: 'b' | 'span' }) {
  const ref = useRef<HTMLElement>(null);
  const from = useRef<number | null>(null);
  const reduce = useReducedMotion();
  useEffect(() => {
    const node = ref.current; if (!node) return;
    const start = from.current ?? 0, first = from.current == null;
    const paint = (v: number) => { node.textContent = prefix + fmt(v, decimals) + suffix; };
    if (reduce) { paint(value); from.current = value; return; }
    const c = animate(start, value, { duration: first ? firstDuration ?? duration * 2.5 : duration, ease: [0.16, 1, 0.3, 1], onUpdate: (v) => { from.current = v; paint(v); } });
    return () => c.stop();
  }, [value, decimals, duration, firstDuration, prefix, suffix, reduce]);
  return createElement(as, { ref, className }, prefix + fmt(0, decimals) + suffix);
}

'use client';
import { LayoutGroup, MotionConfig, motion } from 'framer-motion';
import { useEffect, useRef, useState, useSyncExternalStore } from 'react';
import { ChartCard, type ChartHandle } from './ChartCard';
import { OrderBook, Portfolio, Ticket, Trades, Watchlist, type PortfolioHandle, type TicketHandle, type TradesHandle } from './Panels';
import { EXTRA_TICKER, LedgerStore, fmt } from './store';
import { spring } from './motionPresets';
import './ledger.css';

const TABS = ['Trade', 'Portfolio', 'Markets', 'Earn'];

export interface LedgerDashboardProps {
  /** Run the hands-free tour while nobody touches the page (it pauses for 4 s after any input). Default true. */
  autoplayDemo?: boolean;
  /** Pass your own store (e.g. one fed by a websocket). Defaults to the built-in simulation. */
  store?: LedgerStore;
}

/** Ledger: a trading desk dashboard. Free, MIT, by qodesign.dev. Prices are simulated. */
export function LedgerDashboard(props: LedgerDashboardProps) {
  // Prices, trades and the clock are live and random, so the desk renders after mount.
  // This keeps the server HTML and the first client render identical (no hydration warning in Next.js).
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  if (!mounted) return <div className="ledger" style={{ minHeight: '100vh' }} aria-busy="true" />;
  return <Desk {...props} />;
}

function Desk({ autoplayDemo = true, store: external }: LedgerDashboardProps) {
  const [store] = useState(() => external ?? new LedgerStore(typeof window !== 'undefined' && window.innerWidth < 900 ? 6 : 9));
  useSyncExternalStore(store.subscribe, store.getVersion, store.getVersion);
  const [tab, setTab] = useState('Trade');
  const [clock, setClock] = useState('--:--:--');
  const [toast, setToast] = useState<string | null>(null);
  const toastT = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const chart = useRef<ChartHandle>(null);
  const ticket = useRef<TicketHandle | null>(null);
  const pf = useRef<PortfolioHandle | null>(null);
  const trades = useRef<TradesHandle | null>(null);

  const showToast = (m: string) => { setToast(m); clearTimeout(toastT.current); toastT.current = setTimeout(() => setToast(null), 2600); };

  useEffect(() => {
    if (external) return;
    const id = setInterval(() => { if (!document.hidden) { store.marketTick(); setClock(new Date().toLocaleTimeString('en-GB', { hour12: false })); } }, 1000);
    setClock(new Date().toLocaleTimeString('en-GB', { hour12: false }));
    return () => clearInterval(id);
  }, [store, external]);

  // hands-free tour; real input wins and the tour comes back 4 s after the last input
  useEffect(() => {
    if (!autoplayDemo) return;
    let lastInput = -1e9, stop = false;
    const mark = (e: Event) => { if (e.isTrusted) lastInput = performance.now(); };
    const markMove = (e: PointerEvent) => { if (e.pointerType === 'mouse') mark(e); };
    const evs = ['pointerdown', 'keydown', 'wheel', 'touchstart'] as const;
    evs.forEach((t) => addEventListener(t, mark, { passive: true }));
    addEventListener('pointermove', markMove, { passive: true });
    const idle = () => performance.now() - lastInput > 4000;
    const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const steps: (() => Promise<void>)[] = [
      async () => { const n = chart.current?.count() ?? 64; for (let i = Math.floor(n * 0.45); i < n - 2 && idle() && !stop; i++) { chart.current?.hover(i); await wait(reduce ? 140 : 60); } await wait(700); chart.current?.hover(null); },
      async () => { ticket.current?.setPct(25); await wait(500); ticket.current?.setPct(50); await wait(900); },
      async () => { pf.current?.hot('ETH'); await wait(1300); pf.current?.hot(null); },
      async () => { store.setTf('1H'); await wait(1800); },
      async () => { trades.current?.side('buy'); await wait(1400); trades.current?.side('all'); await wait(500); },
      async () => { ticket.current?.setPct(0); store.setTf('15m'); await wait(1400); },
    ];
    (async () => {
      await wait(2800);
      for (let s = 0; !stop; s++) {
        while ((!idle() || document.hidden) && !stop) await wait(500);
        if (stop) break;
        await steps[s % steps.length]();
        await wait(700);
      }
    })();
    return () => { stop = true; evs.forEach((t) => removeEventListener(t, mark)); removeEventListener('pointermove', markMove); };
  }, [autoplayDemo, store]);

  const tickerItems = [...store.assets.map((a) => ({ s: a.s, px: a.px, chg: a.chg, dp: a.dp })), ...EXTRA_TICKER];
  const tick = tickerItems.map((a) => (
    <span className="tk" key={a.s}><b>{a.s}</b><span className="num">{fmt(a.px, a.dp)}</span><span className={`num ${a.chg >= 0 ? 'up' : 'down'}`}>{a.chg >= 0 ? '▲' : '▼'} {Math.abs(a.chg).toFixed(2)}%</span></span>
  ));

  return (
    <MotionConfig reducedMotion="user">
      <div className="ledger">
        <div className="page">
          <header className="topbar">
            <div className="logo"><svg width="26" height="26" viewBox="0 0 26 26" aria-hidden="true"><rect x="2" y="2" width="22" height="22" rx="7" fill="#161821" stroke="#262A36" /><path d="M8 17V9M13 17v-5M18 17V7" stroke="#C6FF3D" strokeWidth="2.4" strokeLinecap="round" /></svg><span>ledger</span></div>
            <LayoutGroup id="ledger-tabs">
              <nav className="tabs" role="tablist" aria-label="Sections">
                {TABS.map((t) => (
                  <button key={t} role="tab" aria-selected={tab === t} tabIndex={tab === t ? 0 : -1} onClick={() => setTab(t)}>
                    {t}{tab === t && <motion.span layoutId="ledger-ink" className="tab-ink" transition={spring} aria-hidden="true" />}
                  </button>
                ))}
              </nav>
            </LayoutGroup>
            <div className="tb-r">
              <div className="pill"><i className="dot" aria-hidden="true" /><span>Markets open</span><b className="num">{clock}</b></div>
              <div className="pill"><span>Paper account</span></div>
              <div className="avatar" aria-label="Signed in as Ana Ilie" role="img">AI</div>
            </div>
          </header>
          <div className="ticker" aria-label="Market ticker"><div className="ticker-track">{tick}{tickerItems.map((a) => <span className="tk" key={a.s + '-2'} aria-hidden="true"><b>{a.s}</b><span className="num">{fmt(a.px, a.dp)}</span><span className={`num ${a.chg >= 0 ? 'up' : 'down'}`}>{a.chg >= 0 ? '▲' : '▼'} {Math.abs(a.chg).toFixed(2)}%</span></span>)}</div></div>

          <main className="wrap">
            <ChartCard ref={chart} store={store} index={0} />
            <OrderBook store={store} index={1} onPick={(p) => ticket.current?.setPrice(p)} />
            <Ticket store={store} index={2} onToast={showToast} api={ticket} />
            <Portfolio store={store} index={3} api={pf} />
            <Watchlist store={store} index={4} />
            <Trades store={store} index={5} onToast={showToast} api={trades} />
            <p className="foot-credit">Ledger is a free template by <a href="https://qodesign.dev/?utm_source=github&utm_medium=demo&utm_campaign=free_repo" target="_blank" rel="noopener">qodesign.dev</a>. Prices are simulated.</p>
          </main>
        </div>
        <div className={`toast${toast ? ' on' : ''}`} role="status" aria-live="polite"><i>✓</i><span>{toast}</span></div>
      </div>
    </MotionConfig>
  );
}

export default LedgerDashboard;

'use client';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import { useEffect, useMemo, useRef, useState } from 'react';
import { CountUp } from './CountUp';
import { C, fmt, type LedgerStore, type Trade } from './store';
import { cardMotion, spring } from './motionPresets';

/* ---------- order book ---------- */
export function OrderBook({ store, index, onPick }: { store: LedgerStore; index: number; onPick: (p: number) => void }) {
  const cur = store.cur, qd = cur.px > 1000 ? 4 : 2;
  let a = 0; const cumA = store.book.asks.map((r) => (a += r.q));
  let b = 0; const cumB = store.book.bids.map((r) => (b += r.q));
  const max = Math.max(a, b), bp = Math.round((b / (a + b)) * 100);
  const mid = (store.book.asks[0].p + store.book.bids[0].p) / 2;
  const Row = ({ r, cum, k }: { r: { p: number; q: number; flash: number }; cum: number; k: string }) => (
    <div key={k + r.flash} className={`book-row${r.flash === store.tick ? ' flash' : ''}`} onClick={() => onPick(r.p)} role="button" tabIndex={0}
      onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onPick(r.p); } }} aria-label={`Use price ${fmt(r.p, cur.dp)}`}>
      <i style={{ width: `${(cum / max) * 100}%` }} /><span>{fmt(r.p, cur.dp)}</span><span>{fmt(r.q, qd)}</span><span>{fmt(cum, qd)}</span>
    </div>
  );
  return (
    <motion.section className="card book-card" aria-label="Order book" {...cardMotion(index)}>
      <div className="card-h"><h2>Order book</h2><div className="r"><span className="sub">step {store.step()}</span></div></div>
      <div className="book-head"><span>Price (USD)</span><span>Size ({cur.s})</span><span>Total</span></div>
      <div className="book-side asks">{store.book.asks.map((r, i) => ({ r, i })).reverse().map(({ r, i }) => <Row key={'a' + i} k={'a' + i} r={r} cum={cumA[i]} />)}</div>
      <div className="spread"><b className={`num ${cur.px >= cur.open ? 'up' : 'down'}`}>{fmt(mid, cur.dp)}</b><small>spread {fmt(store.book.asks[0].p - store.book.bids[0].p, cur.dp)}</small></div>
      <div className="book-side bids">{store.book.bids.map((r, i) => <Row key={'b' + i} k={'b' + i} r={r} cum={cumB[i]} />)}</div>
      <div className="ratio" aria-hidden="true"><i style={{ background: C.up, width: `${bp}%` }} /><i style={{ background: C.down, width: `${100 - bp}%` }} /></div>
      <div className="ratio-l"><span className="up">B {bp}%</span><span className="down">{100 - bp}% S</span></div>
    </motion.section>
  );
}

/* ---------- order ticket ---------- */
export type TicketHandle = { setPct: (p: number) => void; setPrice: (p: number) => void };
export function Ticket({ store, index, onToast, api }: { store: LedgerStore; index: number; onToast: (m: string) => void; api?: React.MutableRefObject<TicketHandle | null> }) {
  const cur = store.cur;
  const [side, setSide] = useState<'buy' | 'sell'>('buy');
  const [type, setType] = useState<'limit' | 'market'>('limit');
  const [price, setPrice] = useState(cur.px.toFixed(cur.dp));
  const [amt, setAmt] = useState('0.0000');
  const [state, setState] = useState<'idle' | 'busy' | 'done'>('idle');
  const [doneLabel, setDoneLabel] = useState('');
  const reduce = useReducedMotion();
  useEffect(() => { setPrice(cur.px.toFixed(cur.dp)); setAmt('0.0000'); }, [cur.s]); // eslint-disable-line react-hooks/exhaustive-deps
  const pv = type === 'market' ? cur.px : parseFloat(price) || 0;
  const maxAmt = side === 'buy' ? store.cash / (pv || cur.px) : cur.hold;
  const a = parseFloat(amt) || 0, total = a * pv;
  const pct = Math.max(0, Math.min(100, maxAmt ? (a / maxAmt) * 100 : 0));
  const err = a > maxAmt + 1e-9 ? (side === 'buy' ? 'Not enough USD for this amount.' : `You hold ${fmt(cur.hold, 4)} ${cur.s}.`) : '';
  const setPct = (p: number) => setAmt(((maxAmt * p) / 100).toFixed(4));
  if (api) api.current = { setPct, setPrice: (p) => { setType('limit'); setPrice(p.toFixed(cur.dp)); } };
  const submit = () => {
    if (!a || state !== 'idle' || err) return;
    setState('busy');
    setTimeout(() => {
      const { filled } = store.place(side, type, pv, a);
      setDoneLabel(filled ? 'Filled ✓' : 'Order placed ✓'); setState('done');
      onToast(`${side === 'buy' ? 'Bought' : 'Sold'} ${fmt(a, 4)} ${cur.s} at ${fmt(pv, cur.dp)}${filled ? '' : ' (open)'}`);
      setTimeout(() => { setState('idle'); setAmt('0.0000'); }, 1400);
    }, reduce ? 200 : 900);
  };
  return (
    <motion.section className={`card ticket-card${side === 'sell' ? ' sell-mode' : ''}`} aria-label="Place an order" {...cardMotion(index)}>
      <div className="side-t" role="radiogroup" aria-label="Side" onKeyDown={(e) => { if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); setSide((s) => (s === 'buy' ? 'sell' : 'buy')); } }}>
        <motion.span className="knob" aria-hidden="true" animate={{ x: side === 'sell' ? '100%' : '0%', backgroundColor: side === 'sell' ? C.down : C.up }} transition={spring} style={{ transform: 'none' }} />
        {(['buy', 'sell'] as const).map((s) => (
          <button key={s} role="radio" aria-checked={side === s} tabIndex={side === s ? 0 : -1} onClick={() => setSide(s)}>{s === 'buy' ? 'Buy' : 'Sell'}</button>
        ))}
      </div>
      <div className="otype" role="group" aria-label="Order type">
        {(['limit', 'market'] as const).map((t) => <button key={t} aria-pressed={type === t} onClick={() => setType(t)}>{t === 'limit' ? 'Limit' : 'Market'}</button>)}
      </div>
      <div className={`field${type === 'market' ? ' disabled' : ''}`}><label htmlFor="ledger-price">Price</label>
        <input id="ledger-price" inputMode="decimal" autoComplete="off" disabled={type === 'market'} value={type === 'market' ? cur.px.toFixed(cur.dp) : price} onChange={(e) => setPrice(e.target.value)} /><em>USD</em></div>
      <div className="field"><label htmlFor="ledger-amt">Amount</label>
        <input id="ledger-amt" inputMode="decimal" autoComplete="off" value={amt} onChange={(e) => setAmt(e.target.value)} /><em>{cur.s}</em></div>
      <div className="slider">
        <span className="rail" /><span className="fill" style={{ width: `${pct}%` }} />
        {[0, 25, 50, 75, 100].map((s) => <span key={s} className={`stop${s <= pct && pct > 0 ? ' on' : ''}`} style={{ left: `${s}%` }} />)}
        <input type="range" min={0} max={100} step={1} value={Math.round(pct)} aria-label="Share of available balance" onChange={(e) => setPct(+e.target.value)} />
        <span className="thumb" style={{ left: `${pct}%` }} />
      </div>
      <div className="pcts" aria-hidden="true"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div>
      <div className="ferr" role="alert">{err}</div>
      <div className="tot"><span>Total</span><b>{fmt(total)} USD</b></div>
      <button className={`go${state === 'busy' ? ' busy' : ''}${state === 'done' ? ' done' : ''}`} disabled={!!err || a <= 0 || state !== 'idle'} onClick={submit}>
        <span className="sp" aria-hidden="true" />
        <span>{state === 'busy' ? 'Placing order' : state === 'done' ? doneLabel : `${side === 'buy' ? 'Buy' : 'Sell'} ${cur.s}`}</span>
      </button>
      <div className="avail"><span>Available</span><b>{side === 'buy' ? `${fmt(store.cash)} USD` : `${fmt(cur.hold, 4)} ${cur.s}`}</b></div>
    </motion.section>
  );
}

/* ---------- portfolio ---------- */
export type PortfolioHandle = { hot: (s: string | null) => void };
export function Portfolio({ store, index, api }: { store: LedgerStore; index: number; api?: React.MutableRefObject<PortfolioHandle | null> }) {
  const [hot, setHot] = useState<string | null>(null);
  const [drawn, setDrawn] = useState(false);
  if (api) api.current = { hot: setHot };
  useEffect(() => { const t = requestAnimationFrame(() => requestAnimationFrame(() => setDrawn(true))); return () => cancelAnimationFrame(t); }, []);
  const hs = store.holdings(), total = hs.reduce((s, h) => s + h.v, 0);
  const r = 52, circ = 2 * Math.PI * r; let off = 0;
  const h = hs.find((x) => x.s === hot);
  return (
    <motion.section className="card pf-card" aria-label="Portfolio" {...cardMotion(index)}>
      <div className="card-h"><h2>Portfolio</h2><div className="r"><span className="sub">paper money</span></div></div>
      <div className="bal"><small>Total balance</small><CountUp value={total} prefix="$" firstDuration={1.5} /><span className="up">+$1,284.20 (2.74%) today</span></div>
      <div className="donut">
        <svg viewBox="-70 -70 140 140" role="img" aria-label="Allocation by asset" onPointerLeave={() => setHot(null)}>
          {hs.map((x, i) => {
            const frac = x.v / total, len = Math.max(0, frac * circ - 3), o = off; off += frac * circ;
            return <circle key={x.s} className={`seg-arc${hot && hot !== x.s ? ' dim' : ''}${hot === x.s ? ' hot' : ''}`} r={r} stroke={x.col} transform="rotate(-90)"
              strokeDasharray={drawn ? `${len} ${circ - len}` : `0 ${circ}`} strokeDashoffset={-o}
              style={{ transition: `stroke-dasharray 1.1s ${i * 90}ms cubic-bezier(.16,1,.3,1), stroke-width .25s, opacity .25s` }} onPointerEnter={() => setHot(x.s)} />;
          })}
          <text y="-2" fontSize="15" fontWeight="600">{h ? ((h.v / total) * 100).toFixed(1) + '%' : hs.length - 1}</text>
          <text y="14" fontSize="9" fill={C.muted}>{h ? h.s : 'assets'}</text>
        </svg>
        <div className="alloc" onPointerLeave={() => setHot(null)}>
          {hs.map((x) => <button key={x.s} className={hot === x.s ? 'hot' : ''} onPointerEnter={() => setHot(x.s)} onFocus={() => setHot(x.s)} onBlur={() => setHot(null)}><i style={{ background: x.col }} />{x.s}<b>{((x.v / total) * 100).toFixed(1)}%</b></button>)}
        </div>
      </div>
      <div className="assets">
        {hs.filter((x) => x.s !== 'USD').slice(0, 4).map((x) => (
          <div className="asset" key={x.s}><span className="coin" style={{ background: x.col }}>{x.g || x.s[0]}</span>
            <div><b>{x.name}</b><small>{fmt(x.hold, x.px > 1000 ? 4 : 2)} {x.s}</small></div>
            <div className="v">${fmt(x.v)}<small className={x.chg >= 0 ? 'up' : 'down'}>{x.chg >= 0 ? '+' : ''}{x.chg.toFixed(2)}%</small></div></div>
        ))}
      </div>
    </motion.section>
  );
}

/* ---------- watchlist ---------- */
const spark = (h: number[], w = 70, ht = 26) => { const mn = Math.min(...h), mx = Math.max(...h); return h.map((v, i) => `${i ? 'L' : 'M'}${((i / (h.length - 1)) * w).toFixed(1)} ${(ht - 2 - ((v - mn) / (mx - mn || 1)) * (ht - 4)).toFixed(1)}`).join(''); };
export function Watchlist({ store, index }: { store: LedgerStore; index: number }) {
  return (
    <motion.section className="card watch-card" aria-label="Watchlist" {...cardMotion(index)}>
      <div className="card-h"><h2>Watchlist</h2><div className="r"><span className="sub">tap to chart</span></div></div>
      <div className="wl">
        {store.assets.map((a) => { const up = a.px >= a.open, ch = ((a.px - a.open) / a.open) * 100; return (
          <button key={a.s} aria-pressed={a === store.cur} onClick={() => store.setAsset(a.s)} aria-label={`${a.name}, ${fmt(a.px, a.dp)} US dollars, ${ch >= 0 ? 'up' : 'down'} ${Math.abs(ch).toFixed(2)} percent`}>
            <span className="coin" style={{ background: a.col }}>{a.g || a.s[0]}</span><div><b>{a.s}</b><small>{a.name}</small></div>
            <svg viewBox="0 0 70 26" aria-hidden="true"><path d={spark(a.hist)} fill="none" stroke={up ? C.up : C.down} strokeWidth="1.5" /></svg>
            <div className="px">{fmt(a.px, a.dp)}<small className={up ? 'up' : 'down'}>{ch >= 0 ? '+' : ''}{ch.toFixed(2)}%</small></div>
          </button>); })}
      </div>
    </motion.section>
  );
}

/* ---------- trades table ---------- */
type SortKey = 'ts' | 'pair' | 'side' | 'price' | 'amount' | 'total' | 'status';
const COLS: [SortKey, string, boolean][] = [['ts', 'Time', false], ['pair', 'Pair', false], ['side', 'Side', false], ['price', 'Price', true], ['amount', 'Amount', true], ['total', 'Total', true], ['status', 'Status', false]];
const PER = 7;
export type TradesHandle = { side: (s: 'all' | 'buy' | 'sell') => void };
export function Trades({ store, index, onToast, api }: { store: LedgerStore; index: number; onToast: (m: string) => void; api?: React.MutableRefObject<TradesHandle | null> }) {
  const [view, setView] = useState<'history' | 'open'>('history');
  const [side, setSide] = useState<'all' | 'buy' | 'sell'>('all');
  const [q, setQ] = useState('');
  const [sort, setSort] = useState<{ key: SortKey; dir: 'asc' | 'desc' }>({ key: 'ts', dir: 'desc' });
  const [page, setPage] = useState(1);
  const [anim, setAnim] = useState(0);
  const seen = useRef<number | null>(null);
  if (api) api.current = { side: (s) => { setSide(s); setPage(1); setAnim((x) => x + 1); } };
  const rows = useMemo(() => {
    const s = sort.dir === 'asc' ? 1 : -1, k = sort.key, ql = q.trim().toLowerCase();
    return store.trades.filter((t) => (view === 'open' ? t.status === 'open' : t.status === 'filled') && (side === 'all' || t.side === side) && (!ql || t.pair.toLowerCase().includes(ql)))
      .sort((a, b) => (a[k] > b[k] ? 1 : a[k] < b[k] ? -1 : 0) * s);
  }, [store.trades, view, side, q, sort]);
  const pages = Math.max(1, Math.ceil(rows.length / PER)), pg = Math.min(page, pages), sl = rows.slice((pg - 1) * PER, pg * PER);
  const newest = store.trades[0]?.id ?? null;
  const flashId = seen.current !== null && newest !== seen.current ? newest : null;
  useEffect(() => { seen.current = newest; }, [newest]);
  const nums: (number | '…')[] = [];
  for (let p = 1; p <= pages; p++) { if (p === 1 || p === pages || Math.abs(p - pg) <= 1) nums.push(p); else if (nums[nums.length - 1] !== '…') nums.push('…'); }
  const go = (p: number) => { setPage(p); setAnim((x) => x + 1); };
  const openN = store.trades.filter((t) => t.status === 'open').length;
  const dp = (p: number) => (p > 10 ? 2 : 4);
  const cancel = (t: Trade) => { const c = store.cancel(t.id); if (c) onToast(`Cancelled ${c.side} ${c.pair}`); };
  return (
    <motion.section className="card trades-card" aria-label="Orders and trades" {...cardMotion(index)}>
      <div className="tt">
        <div className="tabs2" role="tablist" aria-label="Table">
          <button role="tab" aria-selected={view === 'history'} onClick={() => { setView('history'); go(1); }}>Trade history</button>
          <button role="tab" aria-selected={view === 'open'} onClick={() => { setView('open'); go(1); }}>Open orders <span className="num">{openN}</span></button>
        </div>
        <div className="chips" role="group" aria-label="Side filter">
          {(['all', 'buy', 'sell'] as const).map((s) => <button key={s} aria-pressed={side === s} onClick={() => { setSide(s); go(1); }}>{s === 'all' ? 'All' : s === 'buy' ? 'Buys' : 'Sells'}</button>)}
        </div>
        <label className="tsearch">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></svg>
          <span className="sr">Filter by pair</span><input value={q} onChange={(e) => { setQ(e.target.value); go(1); }} placeholder="Filter by pair" autoComplete="off" />
        </label>
      </div>
      <div className="tbl-wrap">
        <table aria-label="Trades">
          <thead><tr>{COLS.map(([k, label, right]) => (
            <th key={k} className={right ? 'r' : undefined} aria-sort={sort.key === k ? (sort.dir === 'asc' ? 'ascending' : 'descending') : 'none'}>
              <button onClick={() => { setSort((s) => ({ key: k, dir: s.key === k ? (s.dir === 'asc' ? 'desc' : 'asc') : ['ts', 'price', 'amount', 'total'].includes(k) ? 'desc' : 'asc' })); setAnim((x) => x + 1); }}>
                {label}<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M1 3l4 4 4-4" fill="none" stroke="currentColor" strokeWidth="1.6" /></svg></button>
            </th>))}</tr></thead>
          <tbody key={anim}>
            <AnimatePresence initial={false}>
              {sl.length ? sl.map((t, i) => (
                <tr key={t.id} className={t.id === flashId ? 'new' : 'enter'} style={{ ['--r' as string]: i }}>
                  <td className="m">{new Date(t.ts).toLocaleTimeString('en-GB', { hour12: false })}</td><td><b style={{ fontWeight: 600 }}>{t.pair}</b></td>
                  <td><span className={`side-tag ${t.side}`}>{t.side.toUpperCase()}</span></td>
                  <td className="r">{fmt(t.price, dp(t.price))}</td><td className="r">{fmt(t.amount, t.price > 1000 ? 4 : 2)}</td><td className="r">${fmt(t.total)}</td>
                  <td>{t.status === 'open' ? <><span className="st open">open</span> <button className="cancel" aria-label={`Cancel ${t.side} ${t.pair} order`} onClick={() => cancel(t)}>Cancel</button></> : <span className="st filled">filled</span>}</td>
                </tr>
              )) : (
                <tr><td colSpan={7} className="empty">{view === 'open' ? 'No open orders. Place a limit order away from the price to see one here.' : `No trades match “${q || side}”.`}</td></tr>
              )}
            </AnimatePresence>
          </tbody>
        </table>
      </div>
      <div className="pager">
        <span className="num">{rows.length ? (pg - 1) * PER + 1 : 0}–{Math.min(rows.length, pg * PER)} of {rows.length}</span>
        <div className="pages">
          <button aria-label="Previous page" disabled={pg === 1} onClick={() => go(pg - 1)}>‹</button>
          {nums.map((p, i) => p === '…' ? <span key={'e' + i} aria-hidden="true">…</span> : <button key={p} aria-label={`Page ${p}`} aria-current={p === pg ? 'page' : undefined} onClick={() => go(p)}>{p}</button>)}
          <button aria-label="Next page" disabled={pg === pages} onClick={() => go(pg + 1)}>›</button>
        </div>
      </div>
    </motion.section>
  );
}

/* Ledger styles, scoped under .ledger. Same tokens and motion as html/ledger.html. */
.ledger{
  --ink:#0A0A0D; --ink-2:#0E0F14; --panel:#111218; --panel-2:#161821; --line:#262A36; --line-soft:#1C1F29;
  --text:#F4F4F6; --muted:#8A8FA3; --faint:#5C6378;
  --up:#C6FF3D; --down:#FF5C7A; --violet:#8B6CFF; --cyan:#5EE1FF; --amber:#FFB547;
  --font-ui:'Space Grotesk',system-ui,-apple-system,Segoe UI,sans-serif;
  --font-mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,monospace;
  --r-lg:16px; --r-md:10px;
  --ease-out:cubic-bezier(.16,1,.3,1); --ease-spring:cubic-bezier(.34,1.56,.64,1);
}
.ledger *{box-sizing:border-box}
.ledger{margin:0;overflow-x:clip}
.ledger{background:var(--ink);color:var(--text);font-family:var(--font-ui);font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased}
.ledger button,.ledger input{font:inherit;color:inherit}
.ledger button{cursor:pointer}
.ledger :focus-visible{outline:2px solid var(--up);outline-offset:2px;border-radius:6px}
.ledger .num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.ledger .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.ledger .up{color:var(--up)}
.ledger .down{color:var(--down)}
.ledger .page{min-height:100vh;background:radial-gradient(900px 420px at 12% -8%,color-mix(in srgb,var(--up) 7%,transparent),transparent 60%),radial-gradient(1000px 500px at 100% 0%,color-mix(in srgb,var(--violet) 12%,transparent),transparent 60%),var(--ink)}
.ledger .topbar{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:20px;height:60px;padding:0 20px;border-bottom:1px solid var(--line-soft);background:color-mix(in srgb,var(--ink) 82%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
