.ledger .tabs button:hover,.ledger .tabs button[aria-selected="true"]{color:var(--text)}
.ledger .tab-ink{position:absolute;bottom:-1px;left:0;height:2px;border-radius:2px;background:var(--up);transition:transform .45s var(--ease-spring),width .45s var(--ease-spring)}
.ledger .tb-r{margin-left:auto;display:flex;align-items:center;gap:10px}
