.ledger .avatar{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,var(--violet),var(--cyan));color:var(--ink);font-weight:700;font-size:13px}
.ledger .ticker{overflow:hidden;border-bottom:1px solid var(--line-soft);background:var(--ink-2);mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}
.ledger .ticker-track{display:flex;width:max-content;animation:ledger-marquee 48s linear infinite}
.ledger .ticker:hover .ticker-track{animation-play-state:paused}
.ledger .tk{display:flex;align-items:center;gap:8px;height:36px;padding:0 18px;font-size:12px;white-space:nowrap;border-right:1px solid var(--line-soft)}
