@keyframes ledger-marquee{to{transform:translateX(-50%)}}
.ledger .wrap{padding:16px 20px 40px;display:grid;grid-template-columns:minmax(0,1fr) 320px 300px;gap:16px}
.ledger .card{position:relative;background:linear-gradient(180deg,color-mix(in srgb,var(--panel-2) 70%,transparent),var(--panel));border:1px solid var(--line);border-radius:var(--r-lg);padding:16px;min-width:0;
  opacity:0;transform:translateY(14px);animation:ledger-rise .7s var(--ease-out) forwards;animation-delay:calc(var(--i,0) * 70ms)}
